-- Each seed vector has exactly 32 dimensions. Runtime memories use the same
-- deterministic feature-hash encoder, so local and production recall are comparable.
UPSERT INTO agent_memories
(id, location_id, agent_id, memory_type, hazard, region, title, content, importance, confidence, outcome, metadata, embedding, created_at)
VALUES
('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','agent-commander','episode','fire','us-west-2','Malibu wildfire after-action','Pre-positioning two strike teams above the canyon cut initial response by 18 minutes during Santa Ana winds.',.92,.94,'{"label":"success","effectiveness":0.86}'::JSONB,'{"recommended_tactic":"Pre-position Type 3 engines on the ridge before wind onset","source":"historical exercise"}'::JSONB,'[0.17192268,-0.52131393,0.16083089,0.00000000,0.14419322,0.03327536,0.14973911,0.00000000,0.00000000,0.16083089,0.00000000,0.00000000,-0.14973911,0.16637679,-0.14419322,0.00000000,-0.32166179,0.00000000,0.00000000,0.16083089,-0.33275357,-0.14973911,0.28838643,0.19410625,0.00000000,0.00000000,0.14419322,0.32166179,0.00000000,0.00000000,0.00554589,-0.15528500]'::VECTOR, now()-INTERVAL '1 day'),
('20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000004','agent-commander','episode','fire','us-west-2','Oakland Hills wildfire after-action','Targeted vegetation breaks around the urban interface reduced structure exposure despite ember spotting.',.88,.91,'{"label":"success","effectiveness":0.79}'::JSONB,'{"recommended_tactic":"Prioritize defensible-space patrols at the urban edge","source":"historical exercise"}'::JSONB,'[0.16430794,-0.16430794,0.14890407,0.00000000,0.00000000,0.00000000,0.00000000,-0.14890407,0.00000000,0.00000000,0.13350020,0.00000000,-0.61615478,0.14890407,0.17457719,0.00000000,0.00000000,-0.16430794,0.17457719,0.01540387,-0.15917332,0.00000000,0.00000000,0.00000000,0.00000000,0.00000000,-0.02053849,-0.14890407,0.00000000,0.00000000,-0.57507780,-0.12323096]'::VECTOR, now()-INTERVAL '20 hours'),
('20000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000003','agent-commander','episode','multi_hazard','us-west-2','San Bernardino compound-hazard after-action','Distributed shelter staging avoided the primary fault crossing and preserved evacuation capacity after aftershocks.',.95,.93,'{"label":"success","effectiveness":0.88}'::JSONB,'{"recommended_tactic":"Stage shelters on both sides of the fault corridor","source":"historical exercise"}'::JSONB,'[0.19136306,0.31694506,0.01196019,0.00000000,0.15548248,0.20930334,0.18538296,-0.01794029,0.00000000,0.00000000,-0.19136306,0.00000000,-0.66977069,0.20930334,0.00000000,-0.01196019,0.00000000,0.00000000,0.01196019,0.00000000,0.01196019,0.00000000,0.00000000,0.17342277,0.00000000,-0.38272611,0.16146258,0.00000000,0.00000000,0.00000000,0.16744267,0.00000000]'::VECTOR, now()-INTERVAL '12 hours'),
('20000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000008','agent-commander','episode','earthquake','us-west-2','Ridgecrest earthquake after-action','Rapid road inspection and redundant radio channels kept aid moving after a major fault rupture.',.90,.92,'{"label":"success","effectiveness":0.84}'::JSONB,'{"recommended_tactic":"Launch road inspection drones and redundant radio nets immediately","source":"historical exercise"}'::JSONB,'[0.01505590,-0.00752795,-0.22583857,0.00000000,-0.26347833,0.42156533,0.00000000,0.00000000,0.00000000,0.00000000,0.43662124,0.00000000,-0.03763976,0.00000000,-0.19572676,0.22583857,-0.02258386,0.00000000,0.00000000,0.22583857,0.21831062,0.01505590,0.00000000,0.21831062,0.00000000,0.39898148,-0.03763976,0.00000000,0.00752795,-0.24089448,-0.23336652,0.00000000]'::VECTOR, now()-INTERVAL '8 hours');
